// (<= (king_step ?f1 ?r1 ?f2 ?r2) (step ?d ?f1 ?r1 ?f2 ?r2))
fn c47(s: &mut St, d: &Dy, tm: &mut Terms, dw: &mut Dw) -> u64 {
    let mut made = 0u64;
    for ti1 in 0..s.r_step.o2.nz.len() {
        let ix1 = s.r_step.o2.nz[ti1] as usize;
        let mut w1 = s.r_step.o2.w[ix1];
        let mut rm1 = ix1;
        let t1_1 = rm1 % 64;
        rm1 /= 64;
        let t1_0 = rm1;
        let v0 = t1_0;
        let v1 = t1_1 / 8;
        let v2 = t1_1 % 8;
        if w1 == 0 { continue; }
        let hk1 = (v1) * 8 + v2;
        let nb1 = s.r_king_step.or_word(hk1, w1);
        if nb1 != 0 { made += nb1.count_ones() as u64; }
    }
    made
}
